let state = { count: 0, filter: 'all' };   // ① 값은 여기 하나에만

container.addEventListener('click', (e) => {      // ② 일이 일어나면
  const btn = (e.target as HTMLElement).closest('button');
  if (!btn) return;
  state = { ...state, count: state.count + 1 };   //    상태를 바꾸고
  render();                                        //    다시 그린다
});

function render(): void {                          // ③ 상태로 화면을 만든다
  container.innerHTML = `<span>${state.count}</span>`;
}

container.addEventListener('click', (e) => {
  const btn = (e.target as HTMLElement).closest<HTMLElement>('[data-act]');
  if (!btn || !container.contains(btn)) return;

  switch (btn.dataset.act) {
    case 'run':    run(btn.dataset.id!); break;
    case 'copy':   copy(btn.dataset.id!); break;
    case 'remove': remove(btn.dataset.id!); break;
  }
});

type State = { items: Item[]; filter: 'all' | 'done'; };
let state: State = { items: [], filter: 'all' };

function setState(patch: Partial<State>): void {
  state = { ...state, ...patch };   // 새 객체로 갈아 끼운다
  render();                          // 바뀌면 반드시 다시 그린다
}

// 파생값은 저장하지 않고 계산
const visible = state.filter === 'all' ? state.items : state.items.filter((i) => i.done);

// 뼈대는 한 번만 만들고
