const ac = new AbortController();

document.addEventListener('keydown', onKey, { signal: ac.signal });
window.addEventListener('resize', onResize, { signal: ac.signal });
el.addEventListener('click', onClick, { signal: ac.signal });

// 위젯이 닫힐 때 한 줄로 전부 뗀다
function dispose(): void { ac.abort(); }

function draw(container: HTMLElement): void {
  const KEY = 'kl:mywidget:state';
  let state = JSON.parse(localStorage.getItem(KEY) || '{"n":0}');
  const ac = new AbortController();

  container.innerHTML = `<div class="mw-wrap"><div class="mw-body"></div></div>`;
  const body = container.querySelector<HTMLElement>('.mw-body')!;

  container.addEventListener('click', (e) => {              // 위임 하나
    const btn = (e.target as HTMLElement).closest<HTMLElement>('[data-act]');
    if (!btn) return;
    if (btn.dataset.act === 'inc') setState({ n: state.n + 1 });
  }, { signal: ac.signal });

  function setState(patch: object): void {
    state = { ...state, ...patch };
    localStorage.setItem(KEY, JSON.stringify(state));
    render();
  }
  function render(): void {
    body.innerHTML = `<button data-act="inc">${state.n}</button>`;
  }
  render();
}
